def compute_reward(actual_state, golden_state, actual_terminal, expected_terminal,
                  r_disclosure=1.0, p_turns=0.0, p_failed=0.0, hard_violation=False):
    # 考察点: 终态一致性绑定动作三值比对，缺一即 0；Hard-Zero；转人工不进总目标
    if hard_violation:
        return {"r_total": 0.0, "r_complete": 0.0, "success_strict": False}
    r_state = 1.0 if actual_state == golden_state else 0.0
    r_terminal = 1.0 if actual_terminal == expected_terminal else 0.0
    # 乘法门控: 状态正确与动作匹配互为充要，无写库任务动作选错乘数项归零
    r_complete = r_state * r_terminal
    r_total = 0.65 * r_complete + 0.35 * r_disclosure - 0.10 * p_turns - 0.10 * p_failed
    success_strict = (r_complete == 1.0 and r_disclosure == 1.0 and not hard_violation)
    return {"r_total": r_total, "r_complete": r_complete, "success_strict": success_strict}

def group_relative_advantage(rewards, group_ids, eps: float = 1e-8) -> list[float]:
    # 考察点: 组内无 Critic 优势估计、零方差组显式置零
    groups: dict[int, list[float]] = {}
    for r, g in zip(rewards, group_ids):
        groups.setdefault(g, []).append(r)
    stats: dict[int, tuple[float, float]] = {}
    for g, rs in groups.items():
        mean = sum(rs) / len(rs)
        var = sum((x - mean) ** 2 for x in rs) / len(rs)
        stats[g] = (mean, math.sqrt(var))
    advantages = []
    for r, g in zip(rewards, group_ids):
        mean, std = stats[g]
        # 零方差组无梯度信号，显式置 0
        advantages.append(0.0 if std < 1e-7 else (r - mean) / (std + eps))
    return advantages

def pass_at_k(n: int, c: int, k: int) -> float:
    # pass@k = 1 - C(n-c,k)/C(n,k)，连乘展开避免大组合数溢出
    if n - c < k:
        return 1.0
    if c == 0:
        return 0.0
    prod = 1.0
    for i in range(k):
        prod *= (n - c - i) / (n - i)
    return 1.0 - prod

def prob_non_zero_variance(p: float, K: int) -> float:
    # 组内至少一条成功轨迹的概率 1 - (1-p)^K - p^K
    return 1.0 - (1.0 - p) ** K - p ** K

def cispo_token_loss(new_logp, old_logp, advantages, mask,
                     eps_low: float = 1.0, eps_high: float = 4.0,
                     n_norm: float = 2560.0) -> float:
    # ratio 只作权重系数并 detach，梯度始终保留；分母地板抑制短序列尖峰
    loss_sum, mask_sum = 0.0, 0
    for b in range(len(new_logp)):
        adv = advantages[b]
        for t in range(len(new_logp[0])):
            if mask[b][t]:
                ratio = math.exp(new_logp[b][t] - old_logp[b][t])
                weight = min(max(ratio, 1.0 - eps_low), 1.0 + eps_high)
                token_loss = -(weight * adv * new_logp[b][t])  # 梯度只走加权 logp 路径
                loss_sum += token_loss
                mask_sum += 1
    # 分母地板 N_norm：短序列异常梯度被压回安全基线
    return loss_sum / max(mask_sum, n_norm)

def advantage_kl_penalty(advantages, new_logp, ref_logp, mask, kl_coef: float = 0.04):
    # 相对惩罚只罚偏离均值 token，保留合理探索预算
    kl_per_token, total_kl, total_tokens = {}, 0.0, 0
    for b in range(len(new_logp)):
        for t in range(len(new_logp[0])):
            if mask[b][t]:
                kl = new_logp[b][t] - ref_logp[b][t]
                kl_per_token[b][t] = kl
                total_kl += kl
                total_tokens += 1
    avg_kl = total_kl / max(total_tokens, 1)
    adjusted = {}
    for b in range(len(new_logp)):
        for t in range(len(new_logp[0])):
            if mask[b][t]:
                penalty = kl_coef * (avg_kl - kl_per_token[b][t])
                adjusted[b][t] = advantages[b] + penalty
            else:
                adjusted[b][t] = 0.0
    return adjusted, avg_kl

class DisableAdapterContext:
    """上下文内临时旁路 LoRA 增量，前向只走冻结基座权重。"""
    def __init__(self, model):
        self.model = model
        self.prev_state = getattr(model, "adapter_enabled", True)
    def __enter__(self):
        self.model.adapter_enabled = False
    def __exit__(self, exc_type, exc_val, exc_tb):
        self.model.adapter_enabled = self.prev_state

def get_ref_logprobs_zero_ram(model, input_ids):
    with DisableAdapterContext(model):
        return model.forward_logprobs(input_ids)

def step(self, scenarios):
    # 1. 并发 Rollout 收集 K 条轨迹；2. 分组；3. 零方差组过滤；4. 组相对优势
    trajectories = self.model_server.rollout_concurrent(scenarios, self.group_size_k)
    groups: dict[int, list] = {}
    for traj in trajectories:
        groups.setdefault(traj["group_id"], []).append(traj)
    valid, dropped = [], 0
    for g_id, trajs in groups.items():
        rewards = [t["reward"] for t in trajs]
        mean = sum(rewards) / len(rewards)
        var = sum((r - mean) ** 2 for r in rewards) / len(rewards)
        if var > 1e-7:
            std = math.sqrt(var)
            for t in trajs:
                t["advantage"] = (t["reward"] - mean) / (std + 1e-8)
                valid.append(t)
        else:
            dropped += 1
    # 5. Token 级 CISPO 损失与分母地板，6. 反向更新，7. 权重热推，8. 期中门禁
    loss, mask_sum = 0.0, 0
    for t in valid:
        for lp_new, lp_old, m in zip(t["new_logp"], t["old_logp"], t["mask"]):
            if m:
                ratio = math.exp(lp_new - lp_old)
                clipped_w = min(max(ratio, 0.0), 5.0)  # clip 后 detach 作权重
                loss += -(clipped_w * t["advantage"] * lp_new)
                mask_sum += 1
    final_loss = loss / max(mask_sum, self.n_norm)
    self.weights_version += 1
    self.model_server.hot_reload_weights(self.weights_version)
    self.current_step += 1
    return {"step": self.current_step, "loss": final_loss,
            "valid": len(valid), "dropped_groups": dropped,
            "eval_triggered": self.current_step % self.eval_interval == 0}

class AsyncRLCoordinator:
    # 有界陈旧上限 k=1；Merged 单权重下在途旧版本 404 是机制冲突非陈旧度问题
    def __init__(self, max_steps_off_policy: int = 1):
        self.current_policy_version = 0
        self.max_steps_off_policy = max_steps_off_policy
        self.leases = {0: AdapterVersionLease(0)}

    def acquire_turn_lease(self, version_id: int) -> bool:
        lease = self.leases.get(version_id)
        if lease is None or lease.status == "released":
            return False
        lease.active_turns += 1
        return True

    def validate_sample_staleness(self, sample_version: int) -> tuple[bool, str]:
        staleness = self.current_policy_version - sample_version
        if staleness > self.max_steps_off_policy:
            return False, f"STALE_DISCARD: {staleness} > limit"
        return True, "VALID"

    def advance_trainer_version(self) -> int:
        self.current_policy_version += 1
        new_v = self.current_policy_version
        self.leases[new_v] = AdapterVersionLease(new_v)
        for v, lease in self.leases.items():
            if v < new_v - self.max_steps_off_policy and lease.status == "active":
                lease.status = "draining"
        return new_v

    def drain_barrier(self, version_id: int) -> bool:
        lease = self.leases.get(version_id)
        if lease and lease.active_turns == 0:
            lease.status = "released"
            return True
        return False

    def simulate_merged_serving_conflict(self) -> str:
        served = {"agent-grpo@0": "weights_v0"}
        in_flight = "agent-grpo@0"
        served.clear()
        served["agent-grpo@1"] = "weights_v1"
        if in_flight not in served:
            return f"HTTP 404: {in_flight} not found"
        return "SUCCESS"

def token_diff_validator(train_tokens, infer_tokens, context_window: int = 3):
    min_len = min(len(train_tokens), len(infer_tokens))
    divergence_idx = None
    for idx in range(min_len):
        if train_tokens[idx] != infer_tokens[idx]:
            divergence_idx = idx
            break
    if divergence_idx is None and len(train_tokens) != len(infer_tokens):
        divergence_idx = min_len
    if divergence_idx is None:
        return {"identical": True, "divergence_index": None}
    start = max(0, divergence_idx - context_window)
    end = min(max(len(train_tokens), len(infer_tokens)), divergence_idx + context_window + 1)
    return {
        "identical": False,
        "divergence_index": divergence_idx,
        "train_slice": train_tokens[start:end],
        "infer_slice": infer_tokens[start:end],
    }

def batch_token_diff_gate(samples, train_encode_fn, infer_render_fn) -> bool:
    all_passed = True
    for idx, sample in enumerate(samples):
        messages = sample["messages"]
        diff = token_diff_validator(train_encode_fn(messages), infer_render_fn(messages))
        if not diff["identical"]:
            all_passed = False
    return all_passed

class MockSandbox:
    def __init__(self, initial_state):
        self.tables = copy.deepcopy(initial_state)  # 读写隔离，防外部篡改
        self.change_log = []

    def execute(self, tool_name, args):
        if tool_name == "update_db":
            table, key, val = args["table"], args["key"], args["val"]
            self.tables.setdefault(table, {})[key] = val
            self.change_log.append({"op": "update", "table": table, "key": key, "val": val})
            return {"status": "success", "rows_affected": 1}
        return {"status": "error", "message": f"Unknown tool: {tool_name}"}

    def check_strict_success(self, golden_state, expected_terminal, actual_terminal) -> bool:
        state_matched = all(
            self.tables.get(t, {}).get(k) == v
            for t, rows in golden_state.items()
            for k, v in rows.items()
        )
        terminal_matched = actual_terminal == expected_terminal
        return state_matched and terminal_matched

def variance_aware_sample(task_pool, sample_size):
    weights = []
    for task in task_pool:
        p = task.get("historical_pass_rate", 0.5)  # 冷启动置于黄金区
        weights.append(max(p * (1.0 - p), 1e-4))  # 饱和任务权重趋零
    total = sum(weights)
    return random.choices(task_pool, weights=[w / total for w in weights], k=sample_size)

def filter_zero_variance_groups(groups, eps: float = 1e-12):
    kept, dropped = [], []
    for g in groups:
        rewards = g.get("rewards", [])
        if len(rewards) < 2:
            dropped.append(g)
            continue
        mean = sum(rewards) / len(rewards)
        var = sum((r - mean) ** 2 for r in rewards) / len(rewards)
        (kept if var > eps else dropped).append(g)
    return kept, dropped

def _merge_consecutive_roles(messages):
    """合并历史中因过滤工具轮次留下的连续同角色消息。

    LLaMA-Factory 的 ShareGPT 协议对 user/assistant 严格交替有硬性校验，
    剥离 tool 轮后留下的连续 assistant 会被静默丢弃 4028 条；
    合并为单条后信息无损，有效样本恢复 7200 -> 11030 条。
    """
    if not messages:
        return messages
    merged = [messages[0]]
    for msg in messages[1:]:
        if msg["role"] == merged[-1]["role"]:
            merged[-1] = {
                "role": msg["role"],
                "content": merged[-1]["content"] + "\n" + msg["content"],
            }
        else:
            merged.append(msg)
    return merged

def run_react_agent_loop(llm, tools, messages, max_iterations=6):
    # 考察点: 终止条件、多工具执行、tool_call_id 配对、异常回封装不中断主循环
    trajectory = list(messages)
    for iteration in range(1, max_iterations + 1):
        ai_msg = llm(trajectory)
        trajectory.append(ai_msg)
        # 终止判定: 无工具调用即为最终回答
        if not ai_msg.tool_calls:
            return {"status": "success", "final_response": ai_msg.content,
                    "iterations": iteration, "messages": trajectory}
        for call in ai_msg.tool_calls:
            if call["name"] not in tools:
                # 工具不存在: 错误也作为 ToolMessage 喂回模型供纠错
                trajectory.append(ToolMessage(content=f"Error: 未知工具 {call['name']}",
                                              tool_call_id=call["id"], status="error"))
                continue
            try:
                raw = tools[call["name"]](**call.get("args", {}))
                trajectory.append(ToolMessage(content=str(raw), tool_call_id=call["id"], status="success"))
            except Exception as exc:
                # 关键: 即便出错也必须回填对应 tool_call_id 的 ToolMessage，防止配对断裂
                trajectory.append(ToolMessage(content=f"Error: {exc}", tool_call_id=call["id"], status="error"))
    # 达到最大迭代次数: 降级退出而非死循环
    fallback = "已达到最大步数限制，未能完成任务，请缩小指令范围。"
    return {"status": "max_iterations_reached", "final_response": fallback, "messages": trajectory}

def process_agui_event_stream(raw_events, middlewares=None):
    # 考察点: 事件映射矩阵、中间件链、异常必须补发 RUN_FINISHED 闭环
    out_events, run_finished = [], False
    try:
        for raw in raw_events:
            mapped = []  # 每轮重新初始化，未映射类型静默丢弃
            t = raw.get("type", "")
            if t == "run_start":
                mapped = [{"type": "RUN_STARTED", "run_id": raw.get("run_id")}]
            elif t == "on_chat_model_stream":
                if "delta_text" in raw:
                    mapped = [{"type": "TEXT_MESSAGE_CONTENT", "delta": raw["delta_text"]}]
                elif "delta_tool" in raw:
                    mapped = [{"type": "TOOL_CALL_ARGS", "delta": raw["delta_tool"]}]
            elif t == "on_tool_start":
                mapped = [{"type": "TOOL_CALL_START", "tool_name": raw.get("name"), "id": raw.get("id")}]
            elif t == "on_custom_event":
                mapped = [{"type": "CUSTOM", "name": raw.get("name"), "value": raw.get("value")}]
            elif t == "on_interrupt":
                # 中断透出契约: 发 CUSTOM on_interrupt 后立即闭合本轮，不挂死前端
                mapped = [{"type": "CUSTOM", "name": "on_interrupt", "value": raw.get("payload")},
                          {"type": "RUN_FINISHED", "run_id": raw.get("run_id")}]
                run_finished = True
            elif t == "run_finish":
                mapped = [{"type": "RUN_FINISHED", "run_id": raw.get("run_id")}]
                run_finished = True
            # 中间件链: 逐级过滤或改写事件
            for mw in (middlewares or []):
                mapped = [e for ev in mapped for e in mw(ev)]
            out_events.extend(mapped)
            if run_finished:
                break
    except Exception as exc:
        # 异常兜底: 确保前端 SSE 连接确定性闭合，绝不悬挂
        out_events.append({"type": "RUN_ERROR", "message": str(exc)})
        if not run_finished:
            out_events.append({"type": "RUN_FINISHED", "run_id": "error_closed"})
    return out_events

class PersistentTeammateManager:
    # 一成员一持久线程: 相同 (team_thread, member_id) 稳定复用同一 teammate_thread
    def get_or_create_teammate_thread(self, member_agent_id):
        if member_agent_id not in self._threads:
            raw = f"{self.team_thread_id}::{member_agent_id}".encode("utf-8")
            # 确定性派生: 重新委派/追问都能定位到同一线程与沙箱
            self._threads[member_agent_id] = "tm_th_" + hashlib.sha256(raw).hexdigest()[:16]
        return self._threads[member_agent_id]

class TeamAssignmentScheduler:
    MAX_ACTIVE_SLOTS = 3  # 槽位硬限制: 防模型发散连续派发打爆算力
    def submit_assignment(self, member_agent_id, teammate_thread_id, instruction, mode):
        asgn = Assignment(member_agent_id=member_agent_id,
                          teammate_thread_id=teammate_thread_id,
                          instruction=instruction, delegation_mode=mode)
        if len(self.active_slots) < self.MAX_ACTIVE_SLOTS:
            asgn.status = "working"
            self.active_slots[asgn.assignment_id] = asgn
        else:
            asgn.status = "queued"  # 溢出进入持久 FIFO 队列，而非拒绝
            self.fifo_queue.append(asgn)
        return asgn
    def on_teammate_finished(self, assignment_id, result, status="succeeded"):
        asgn = self.active_slots.pop(assignment_id, None)
        if asgn:
            asgn.status, asgn.result = status, result
        # 释放槽位后立即从 FIFO 队列唤醒下一项
        if self.fifo_queue and len(self.active_slots) < self.MAX_ACTIVE_SLOTS:
            nxt = self.fifo_queue.popleft()
            nxt.status = "working"
            self.active_slots[nxt.assignment_id] = nxt
            return nxt
        return None

class SubgraphToolMiddleware:
    """红线: 不改子图契约、不改第三方包，以中间件拦截取代 CompiledSubAgent"""
    def __init__(self, subgraph_registry,
                 whitelist_fields=("data_envelope", "visualization_result", "report_draft")):
        self._registry = subgraph_registry
        self._whitelist = set(whitelist_fields)

    def wrap_tool_call(self, tool_call, main_state, next_handler):
        # 考察点: 拦截、隔离子图执行、白名单回写防私有变量泄漏
        if tool_call.get("name") not in self._registry:
            return next_handler(tool_call)  # 未命中子图: 透传给普通工具执行器
        subgraph = self._registry[tool_call["name"]]
        # 隔离执行: 拷贝完整上下文，防止子图对主图内存状态造成污染
        isolated_state = copy.deepcopy(main_state)
        subgraph_result = subgraph.invoke(isolated_state)
        tool_msg = ToolMessage(content=f"子图 {tool_call['name']} 执行成功",
                               tool_call_id=tool_call.get("id", "call_default"),
                               status="success")
        # 白名单回写: 仅预定领域字段同步回主图，子图私有变量不泄漏
        state_update = {"messages": [tool_msg]}
        for field in self._whitelist:
            if field in subgraph_result:
                state_update[field] = subgraph_result[field]
        # 通过 Command 机制原子更新主图状态
        return Command(update=state_update)

def run_react_agent_loop(llm, tools, messages, max_iterations=6):
    # 考察点: 终止条件、tool_call_id 配对、异常回封装不中断主循环
    trajectory = list(messages)
    for iteration in range(1, max_iterations + 1):
        ai_msg = llm(trajectory)
        trajectory.append(ai_msg)
        # 终止判定: 无工具调用即为最终回答
        if not ai_msg.tool_calls:
            return {"status": "success", "final_response": ai_msg.content,
                    "iterations": iteration, "messages": trajectory}
        # 遍历执行全部工具调用; 异常封装成 ToolMessage 喂回模型供纠错
        for call in ai_msg.tool_calls:
            call_id, name = call["id"], call["name"]
            if name not in tools:
                trajectory.append(ToolMessage(content=f"Error: 未知工具 {name}",
                                              tool_call_id=call_id, status="error"))
                continue
            try:
                result = tools[name](**call.get("args", {}))
                trajectory.append(ToolMessage(content=str(result), tool_call_id=call_id))
            except Exception as exc:
                trajectory.append(ToolMessage(content=f"Error: {exc}",
                                              tool_call_id=call_id, status="error"))
    # 超限降级退出, 不抛异常
    fallback = "已达到最大步数限制，未能完成任务，请缩小指令范围。"
    trajectory.append(AIMessage(content=fallback))
    return {"status": "max_iterations_reached", "final_response": fallback,
            "iterations": max_iterations, "messages": trajectory}

def process_agui_event_stream(raw_events, middlewares=None):
    # 考察点: 内部事件到 AG-UI 协议映射、中间件链、异常必须补发 RUN_FINISHED 闭环
    out, run_finished, current_step = [], False, None
    try:
        for raw in raw_events:
            t, mapped = raw.get("type", ""), []
            if t == "run_start":
                mapped.append({"type": "RUN_STARTED", "run_id": raw.get("run_id")})
            elif t == "on_chain_start":
                current_step = raw.get("node_name", "agent")
                mapped.append({"type": "STEP_STARTED", "step_name": current_step})
            elif t == "on_chain_end":
                mapped.append({"type": "STEP_FINISHED", "step_name": current_step or "agent"})
            elif t == "on_chat_model_stream":
                if "delta_text" in raw:
                    mapped.append({"type": "TEXT_MESSAGE_CONTENT", "delta": raw["delta_text"]})
                elif "delta_tool" in raw:
                    mapped.append({"type": "TOOL_CALL_ARGS", "delta": raw["delta_tool"]})
            elif t == "on_tool_start":
                mapped.append({"type": "TOOL_CALL_START", "tool_name": raw.get("name"), "id": raw.get("id")})
            elif t == "on_tool_end":
                mapped.append({"type": "TOOL_CALL_RESULT", "output": raw.get("output"), "id": raw.get("id")})
            elif t == "on_interrupt":
                # 中断透出后立即闭合本轮流, 不挂死前端
                mapped += [{"type": "CUSTOM", "name": "on_interrupt", "value": raw.get("payload")},
                           {"type": "RUN_FINISHED", "run_id": raw.get("run_id")}]
                run_finished = True
            elif t == "run_finish":
                mapped.append({"type": "RUN_FINISHED", "run_id": raw.get("run_id")})
                run_finished = True
            # 中间件链逐级过滤或改写事件
            for mw in middlewares or []:
                mapped = [ev for batch in (mw(e) for e in mapped) for ev in batch]
            out.extend(mapped)
            if run_finished:
                break
    except Exception as exc:
        # 异常兜底: 确定性地闭合 SSE 连接, 绝不悬挂
        if current_step:
            out.append({"type": "STEP_FINISHED", "step_name": current_step})
        out.append({"type": "RUN_ERROR", "message": str(exc)})
        if not run_finished:
            out.append({"type": "RUN_FINISHED", "run_id": "error_closed"})
    return out

class PersistentTeammateManager:
    """一成员一持久线程: 相同 (team_thread, member_id) 稳定复用同一 teammate_thread"""
    def __init__(self, team_thread_id):
        self.team_thread_id = team_thread_id
        self._threads = {}

    def get_or_create_teammate_thread(self, member_agent_id):
        # 线程 ID 由联合键确定性派生, 重派不换线程即保留成员上下文与沙箱
        if member_agent_id not in self._threads:
            raw = f"{self.team_thread_id}::{member_agent_id}".encode()
            self._threads[member_agent_id] = "tm_th_" + hashlib.sha256(raw).hexdigest()[:16]
        return self._threads[member_agent_id]


class TeamAssignmentScheduler:
    MAX_ACTIVE_SLOTS = 3  # 准入硬限制

    def __init__(self):
        self.active_slots = {}
        self.fifo_queue = deque()

    def submit_assignment(self, member_agent_id, tm_thread, instruction, mode):
        asgn = Assignment(member_agent_id=member_agent_id, teammate_thread_id=tm_thread,
                          instruction=instruction, delegation_mode=mode)
        if len(self.active_slots) < self.MAX_ACTIVE_SLOTS:
            asgn.status = "working"
            self.active_slots[asgn.assignment_id] = asgn
        else:
            asgn.status = "queued"   # 溢出进持久 FIFO 队列
            self.fifo_queue.append(asgn)
        return asgn

    def on_teammate_finished(self, assignment_id, result, status="succeeded"):
        asgn = self.active_slots.pop(assignment_id, None)
        if asgn:
            asgn.status, asgn.result = status, result
        # 槽位释放, 立即从 FIFO 唤醒下一项
        if self.fifo_queue and len(self.active_slots) < self.MAX_ACTIVE_SLOTS:
            nxt = self.fifo_queue.popleft()
            nxt.status = "working"
            self.active_slots[nxt.assignment_id] = nxt
            return nxt
        return None

class OrchestratorDelegationTools:
    SOFT_WAIT_TIMEOUT_SECONDS = 300.0  # 5 分钟软等待窗口

    def __init__(self, teammate_manager, scheduler):
        self.teammate_manager = teammate_manager
        self.scheduler = scheduler

    def delegate_and_wait(self, member_agent_id, instruction, exec_time=1.0):
        tm_thread = self.teammate_manager.get_or_create_teammate_thread(member_agent_id)
        asgn = self.scheduler.submit_assignment(member_agent_id, tm_thread, instruction, "waiting")
        if asgn.status == "queued":
            return {"status": "queued", "assignment_id": asgn.assignment_id}
        if exec_time > self.SOFT_WAIT_TIMEOUT_SECONDS:
            # 软超时不判失败: 交由 Orchestrator 决策追加等待 / 转后台 / 取消
            asgn.status = "soft_timeout"
            return {"status": "soft_timeout", "assignment_id": asgn.assignment_id}
        result = self._execute(asgn)
        self.scheduler.on_teammate_finished(asgn.assignment_id, result)
        return {"status": "succeeded", "assignment_id": asgn.assignment_id,
                "summary": result["summary"]}

    def delegate_in_background(self, member_agent_id, instruction):
        # 异步分派: 立即返回持久 assignment_id, 非阻塞
        tm_thread = self.teammate_manager.get_or_create_teammate_thread(member_agent_id)
        asgn = self.scheduler.submit_assignment(member_agent_id, tm_thread, instruction, "background")
        return {"status": asgn.status, "assignment_id": asgn.assignment_id,
                "teammate_thread_id": tm_thread}

def reciprocal_rank_fusion(ranked_lists, k=60, weights=None):
    # 公式: RRF_Score(d) = sum_m w_m / (k + rank_m(d))
    if weights is None:
        weights = [1.0] * len(ranked_lists)
    doc_scores = {}
    for ranked_list, w in zip(ranked_lists, weights):
        for rank, doc_id in enumerate(ranked_list, start=1):  # 1-based rank
            # 只用排名不用原始分: 排名天然无量纲, k=60 压平头部差距、保护长尾
            doc_scores[doc_id] = doc_scores.get(doc_id, 0.0) + w / (k + rank)
    return sorted(doc_scores.items(), key=lambda item: item[1], reverse=True)

def bradley_terry_rm_loss(r_chosen, r_rejected):
    # 公式: L_BT = -log sigma(r_w - r_l) = log(1 + exp(-(r_w - r_l)))
    diff = r_chosen - r_rejected
    # 数值稳定形式: diff 极大时 exp 下溢为 0, 极小时退化为线性 -diff
    if diff > 30.0:
        return math.exp(-diff)
    elif diff < -30.0:
        return -diff
    return math.log(1.0 + math.exp(-diff))

class ContinuousBatchingScheduler:
    def __init__(self, block_manager):
        self.mgr = block_manager
        self.waiting_queue, self.running_queue = [], []

    def step(self):
        # 1. 准入等待队列 (Prefill 随到随入, 不等整批)
        for req in list(self.waiting_queue):
            if self.mgr.allocate(req["seq_id"], req["prompt_tokens"]):
                self.waiting_queue.remove(req)
                self.running_queue.append(req)
            else:
                break  # 显存块不足, 等待后续释放
        # 2. 运行中请求各生成 1 Token (Decode), 与 Prefill 混排
        finished, preempted = [], []
        for req in list(self.running_queue):
            if not self.mgr.append_token(req["seq_id"], f"tok_{req['generated_tokens']}"):
                # 显存不足抢占: 释放块并踢回队首, 重计算/换出而非失败
                self.mgr.free(req["seq_id"])
                self.running_queue.remove(req)
                self.waiting_queue.insert(0, req)
                preempted.append(req["seq_id"])
                continue
            req["generated_tokens"] += 1
            if req["generated_tokens"] >= req["max_new_tokens"]:
                self.mgr.free(req["seq_id"])
                self.running_queue.remove(req)
                finished.append(req["seq_id"])
        return {"finished": finished, "preempted": preempted}

def bradley_terry_rm_loss(r_chosen, r_rejected):
    # L_BT = -log sigmoid(r_w - r_l) = log(1 + exp(-(r_w - r_l)))
    diff = r_chosen - r_rejected
    if diff > 30.0:
        return math.exp(-diff)
    if diff < -30.0:
        return -diff
    return math.log(1.0 + math.exp(-diff))


def compute_step_rewards_with_kl(outcome_reward, policy_logp, ref_logp, beta=0.05):
    # 逐 token KL 惩罚; 结果奖励只叠加在最后一个 token
    rewards = []
    for t, (lp, ref) in enumerate(zip(policy_logp, ref_logp)):
        r_t = -beta * (lp - ref)
        if t == len(policy_logp) - 1:
            r_t += outcome_reward
        rewards.append(r_t)
    return rewards


def rlhf_ppo_step(outcome_reward, policy_logp, ref_logp, values, beta=0.05, eps=0.2):
    # 四模型协同: Policy 生成 / Ref 冻结算 KL / RM 打分 / Critic 估 V
    step_rewards = compute_step_rewards_with_kl(outcome_reward, policy_logp, ref_logp, beta)
    advantages = compute_gae(step_rewards, values, gamma=1.0, lam=0.95)
    # PPO-Clip: ratio 截断后取悲观目标
    ratio = math.exp(policy_logp[0] - policy_logp[0])
    adv = advantages[0]
    surr1 = ratio * adv
    surr2 = min(max(ratio, 1 - eps), 1 + eps) * adv
    return -min(surr1, surr2)
